Running command: cat > /tmp/compare_modes.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "h3api.h"
#include "polyfill.h"
#include "polygon.h"

int main(int argc, char** argv) {
    FILE* fp = fopen(argv[1], "rb");
    if (!fp) { perror("open"); return 1; }
    int numVerts;
    fread(&numVerts, sizeof(int), 1, fp);
    LatLng* verts = malloc(sizeof(LatLng)*numVerts);
    fread(verts, sizeof(LatLng), numVerts, fp);
    fclose(fp);

    GeoLoop gl = {.numVerts = numVerts, .verts = verts};
    GeoPolygon poly = {.geoloop = gl, .numHoles = 0, .holes = NULL};

    int res = atoi(argv[2]);

    for (uint32_t flags = 0; flags < CONTAINMENT_INVALID; flags++) {
        int64_t sz;
        H3Error err = maxPolygonToCellsSizeExperimental(&poly, res, flags, &sz);
        if (err) { printf("flags=%u err=%d\n", flags, err); continue; }
        H3Index* out = calloc(sz, sizeof(H3Index));
        H3Error err2 = polygonToCellsExperimental(&poly, res, flags, out);
        int64_t cnt = 0;
        for (int64_t i = 0; i < sz; i++) if (out[i]) cnt++;
        printf("flags=%u sz=%lld cnt=%lld err2=%d %s\n", flags, (long long)sz, (long long)cnt, err2, cnt>sz?"OVERFLOW":"");
        free(out);
    }
    free(verts);
    return 0;
}
EOF
